#!/bin/bash
# custody_sacct_probe.sh: login-only, read-only probe of custody's two COV2D-fence sacct reads (limitation-resolver,
# 2026-11-23, the director's real-sacct rule). Generated by gen_probe.py from fd_rpd_reco_custody.py
# sha256 6f529d8930ecdbe0371475eaac618945955654261c4afa14f2bc30da679c5c39. It runs each read once, with stderr merged, prints its rc and output, and writes nothing.
# No squeue, no job, nothing written on the cluster.
echo "== host $(hostname) utc $(date -u +%FT%TZ) local $(date +%FT%T%z)"
start=$(date -d "@$(( $(date +%s) - 14 * 86400 ))" +%Y-%m-%dT%H:%M:%S) || { echo "STOP: start date failed"; exit 3; }
echo "== named: sacct -X -n -P -j 60909280,60911676 -S 2026-11-05T00:00:00 -E 2026-11-08T00:00:00 -o JobIDRaw,JobName,State"
out=$(sacct -X -n -P -j 60909280,60911676 -S 2026-11-05T00:00:00 -E 2026-11-08T00:00:00 -o JobIDRaw,JobName,State 2>&1); nrc=$?
echo "named rc=$nrc"
printf '%s\n' "$out" | sed 's/^/named: /'
echo "== family (start $start): sacct -X -n -P -u josephrb -S $start -E now -o JobIDRaw,JobName,State"
out=$(sacct -X -n -P -u josephrb -S "$start" -E now -o JobIDRaw,JobName,State 2>&1); frc=$?
echo "family rc=$frc"
printf '%s\n' "$out" | sed 's/^/family: /'
echo "== end utc $(date -u +%FT%TZ)"
[ "$nrc" -eq 0 ] && [ "$frc" -eq 0 ]
